WITH cleaned AS (SELECT *, CAST(sqft AS STRING) AS sqft_str FROM stores WHERE opened_date >= DATE '2023-09-07' AND region IS NOT NULL) SELECT id, store_name, NTILE(5) OVER (PARTITION BY YEAR(opened_date), city ORDER BY sqft DESC, id) AS sqft_bucket, AVG(sqft) OVER (PARTITION BY MONTH(opened_date), city ORDER BY sqft, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS sqft_avg_5, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('YEAR', opened_date), region ORDER BY sqft DESC NULLS FIRST) AS sqft_dense_rank, AVG(sqft) OVER w_ordered AS sqft_avg_2_prior FROM cleaned WINDOW w_ordered AS (PARTITION BY region ORDER BY opened_date, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING);
